new='''def format_value(value: Value) -> str:
    """Render one cell."""
    if value is None:
        return "NULL"
    if value is True:
        return "TRUE"
    if value is False:
        return "FALSE"
    return str(value)


def format_result(result: QueryResult) -> str:
    """Render a QueryResult as text."""
    if not result.columns:
        return f"OK ({result.row_count} rows affected)"
    cells = [[format_value(v) for v in row] for row in result.rows]
    widths = [
        max([len(c)] + [len(r[i]) for r in cells])
        for i, c in enumerate(result.columns)
    ]
    lines = [
        " | ".join(c.ljust(w) for c, w in zip(result.columns, widths)),
        " | ".join("-" * w for w in widths),
    ]
    for r in cells:
        lines.append(" | ".join(c.ljust(w) for c, w in zip(r, widths)))
    n = len(result.rows)
    lines.append("(1 row)" if n == 1 else f"({n} rows)")
    return "\\n".join(lines)


def run_repl(
    stdin: TextIO,
    stdout: TextIO,
    stderr: TextIO,
    engine: Optional[Engine] = None,
) -> int:
    """Read SQL from stdin and execute it."""
    if engine is None:
        engine = Engine()

    def run(sql: str) -> None:
        try:
            result = engine.execute(sql)
            stdout.write(format_result(result) + "\\n")
        except MiniDBError as e:
            stderr.write(f"ERROR: {e}\\n")

    buf = ""
    for line in stdin:
        if line.strip() == ".exit":
            break
        buf += line
        if buf.strip().endswith(";"):
            run(buf)
            buf = ""
    else:
        if buf.strip():
            run(buf)
    return 0


def main(argv: Optional[list[str]] = None) -> int:
    """CLI entry point."""
    return run_repl(sys.stdin, sys.stdout, sys.stderr)


'''
